// Glance → the cockpit workspace (#2206), AS GRAPH SOURCE (#4185, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the glance lib/hook surface via the glance graph-platform,
// and the sibling components via the glance graph-platform too). Behaviour runs here.
// Glance workspace (#2206, epic #2205) — the workspace-level mission control. A tabbed Screen (#2223):
// NETWORK (the project-network map: every project a node, dependencies as edges, cross-project CYCLES as
// coordination hazards) paired with FLEET (the live orchestration analytics for the active project's
// fleet). Network toolbar (search · cycle pill · zoom/fit) · sidebar (projects + hazards) · transform
// graph canvas · project/contract inspector. Nodes are the user's REAL projects; the topology is
// clearly-marked SAMPLE until a real cross-project dependency model lands (epic slice 4). Clicking a
// project will drill to its live agent network (L2, later slice) — for now it opens the inspector. The
// pan/zoom shell is the shared GraphCanvas template + useGraphViewport (#2208, epic #2197 slice 2).
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { demoSnapshot } from "@/store/demoSnapshot";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { useConfirmDialog, usePromptDialog } from "@/shared/ui/overlay/promptDialog";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { Screen } from "@/shared/ui/layouts/Screen";
import { type TabItem } from "@/shared/ui/layouts/TabBar";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { useScreenDescriptor } from "@/shared/hooks/useScreenDescriptor";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { usePoll } from "@/shared/hooks/usePoll";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { resolveKitLibraryRefs } from "@/features/designs";
import { GlanceCanvas, GlanceOverlays } from "@/features/glance/GlanceCanvas";
import { cellRect, placeByDirection, releaseCell, occupants, clampCell, DEFAULT_CELL, type CellSize, type MorphPlacement } from "@/features/glance/lib/morphGrid";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";
import { completedPanes } from "@/features/glance/lib/resumeProject";
import { livePaneIds as livePaneIdsOf } from "@/app/console/lib/livePanes";
import { decideExpand } from "@/features/glance/lib/expandNode";
import { ensureClaudeRunning } from "@/shared/lib/session/ensureClaudeRunning";
import { buildGraph, focusSets, isBandNode, isArchitectNodeId, nodeKindRank, resolveGridAnchor, HEALTH_META, ROLE_COLOR } from "@/features/glance/lib/glanceGraph";
import { timedSync } from "@/shared/lib/core/perf";
import { buildGlanceData } from "@/features/glance/lib/glanceData";
import type { DeclaredIntegrationRow, ConnectorStatusRow } from "@/features/glance/lib/integrationNodes";
import { fleetGraphToGlance, nodeHasLiveSession, withPreviewNode, PREVIEW_NODE_ID } from "@/features/glance/lib/glanceFleet";
import { isAppProject, livePanesForDrilledProject, studioPaneIdForNode, studioNodeHome, applyStudioLiveStatus, withProjectRequestNodes, withUnparentedRequestNodes, withDirectorRequestNodes, splitDirectorSessionTiers } from "@/features/glance/lib/studioProject";
import { isStudioId, useStudioViewers } from "@/features/studio-sessions";
import { DEBUG_STUDIO_PANE_PREFIX } from "@/shared/lib/session/systemSessions";
import { useProjectComplete } from "@/features/glance/lib/useProjectComplete";
import { usePreviewReview } from "@/features/glance/usePreviewReview";
import type { PreviewSource } from "@/shared/lib/preview/previewSource";
import { useGlanceProjects, applyFaultHealth, applyOffHealth } from "@/features/glance/lib/useGlanceProjects";
import { useGlanceFaults } from "@/features/glance/lib/useGlanceFaults";
import { applyStallHealth, applyFleetLiveStatus, liveWaits } from "@/features/glance/lib/agentStall";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { useProjectFleet, useFleetGraph } from "@/features/glance/lib/useProjectFleet";
import { useStreamProgress } from "@/features/glance/lib/useStreamProgress";
import { withStreamProgress } from "@/features/glance/lib/streamProgress";
import { useFleetIssueState } from "@/features/glance/lib/useFleetIssueState";
import type { DockPlan } from "@/features/glance/GlanceChatDock";
import { fleetPlanProgress, unionDone, mergeStreamProgress } from "@/features/glance/lib/fleetPlanProgress";
import { useFleetHeld } from "@/features/glance/lib/useFleetHeld";

// The agent-health watchdog (#2541) polls the coord log on a slow cadence — a stall is a minutes-scale
// event, so per-second rebuilds aren't worth it.
const STALL_POLL_MS = 15_000;
/** How often the integration band re-reads its verdicts. Slower than the stall poll: a verdict only
 *  moves when the Integrator runs a check, which is a human-scale event, not a per-second one. */
const INTEGRATION_POLL_MS = 30_000;

/** The two tabs that are NOT networks. `fleet` is a dashboard, not a graph; `network` is the
 *  all-projects view that predates networks and stays as the "everything" lens — a user with no
 *  networks yet still has a Glance.
 *
 *  Neither id can collide with a network id: every network id is minted `network-<slug>` with a
 *  non-empty slug, so `network` (no hyphen) and `fleet` are unreachable by that grammar. */
/* THERE ARE NO FIXED TABS. Every Glance tab is a DOMAIN — a network, its projects, and the one
   architect that runs discovery for them.
   An `All projects` lens used to sit here. It was removed on the maintainer's direction: a tab that is
   not a domain is a different kind of thing wearing the same chrome, and the kitchen-sink domain
   (`kitchen`) already holds everything not yet organised, so nothing needs an everything-view.
   The corollary is that the network list can never be legitimately empty — `hydrateNetworks`
   reconciles a missing network into existence and falls back to `kitchen` — because an empty list here
   is now an empty WORKSPACE rather than a graph with one lens. */

/** A STABLE empty fleet (#4102). `?? []` would mint a new array every render, and the issue-state
 *  overlay memoises its query on stream identity — a fresh array each time would rebuild the query
 *  and refetch forever. */
const NO_STREAMS: never[] = [];

/** The drill graph for a project with no fleet AND no director: empty, because that is what is true. */
const EMPTY_FLEET_DATA = { rawNodes: [], rawEdges: [], sample: false };


export function GlanceWorkspace({ pageOverride }: { pageOverride?: string } = {}) {
  const planFleet = useAppStore((s) => s.planFleet);
  const personas = useAppStore((s) => s.personas);
  // The OPEN-REQUESTS poll is GONE (#debug-nodes-hang-off-the-session-that-filed-them). It existed to
  // decide whether to fold a generic `debugger` node into a drill while any request was unresolved,
  // because the real per-request sessions were gated behind a Settings toggle that defaulted off. Both
  // halves of that are gone: the toggle, and the stand-in node it was compensating for. `RequestSessionsMount`
  // now holds a session per open request unconditionally and publishes them, so the drill renders the
  // ACTUAL sessions — labelled with their requests and edged to whoever filed them — instead of a count.
  // The live request sessions, so each is a visible, openable node in this graph — carrying the origin
  // and title the node needs to be labelled and edged to the session that filed it.
  const activeDebugRequests = useAppStore((s) => s.activeDebugRequests);
  // Launched project panes (#2542): the set of pane ids a launch or a wake STARTED — a symmetric "this agent
  // has a terminal" signal for BOTH workers AND the DIRECTOR. The earlier per-pane runtime signals (roster /
  // status / paneClaudeActive) covered workers but never the director — it isn't a stream (so it's off the
  // roster) and sits idle between prompts. It used to be membership of an open console tab; project panes
  // live only here now (`project-fleet-panes-live-only-in-glance`), so it is the launch generation
  // `TerminalHost` holds and mounts. Ended/disabled/dormant panes drop out.
  const launchGen = useAppStore((s) => s.paneLaunchGen);
  const endedPanes = useAppStore((s) => s.endedPanes);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  // ONE RULE, shared with the status bar (`@/app/console/lib/livePanes`), because two counters that
  // answer "is this live" separately will disagree and one of them will be wrong. This one used to
  // read only `endedPanes`/`disabledPanes` and miss DORMANT — the state a reaped pane is left in —
  // so "End 8 sessions" offered to kill the eight parked directors the reaper had just reclaimed.
  const dormantPanes = useAppStore((s) => s.dormantPanes);
  const livePaneIds = useMemo(
    () => livePaneIdsOf(launchGen, { endedPanes, disabledPanes, dormantPanes }),
    [launchGen, endedPanes, disabledPanes, dormantPanes],
  );
  // The REAL project set: published GitHub projects merged with local drafts (keyed by the plan key so the
  // drill resolves each project's fleet). A "planning" status marks a planned project; "live" (app running)
  // is the detection follow-up.
  const projectsBase = useGlanceProjects();
  const loadDemoState = useAppStore((s) => s.loadDemoState);
  // Resume wiring (#glance-resume): jump to a live agent's Console pane, resume a single dormant pane in
  // place, and find a project's existing build tab so a project-resume can prefer jumping over rebuilding.
  // Resume ONE pane in place when its build tab is still open (#expanding-a-node-resumes-its-session) —
  // the cheap path behind an expand click, before falling back to bringing the whole fleet back.
  const resumePaneSession = useAppStore((s) => s.resumePaneSession);
  // Opening a base-studio-code studio node reveals its session on its own workspace page (#glance-resume);
  // `paneClaudeActive` tells us whether that stable-id session is already running.
  const paneClaudeActive = useAppStore((s) => s.paneClaudeActive);
  const projectLinks = useAppStore((s) => s.projectLinks);
  // Re-read the contracts whenever this workspace mounts (#architect-wires-project-relationships).
  //
  // `projectLinks` is a write-through cache and boot was its ONLY authoritative read, which held while
  // the app was the only writer. It no longer is: the architect edits contracts through
  // `bsc project link` from its own session, and that write lands in the global store with nothing to
  // tell zustand. Without this the relationship the user just asked for stays invisible until the next
  // app restart — which reads as "it did not work", not as "the view is stale".
  //
  // On mount rather than on a poll: Glance is where the network is drawn, so opening it is exactly when
  // a re-read is worth one process spawn, and a poll would pay that cost every few seconds forever.
  const hydrateProjectLinks = useAppStore((s) => s.hydrateProjectLinks);
  useEffect(() => { void hydrateProjectLinks(); }, [hydrateProjectLinks]);
  // The UI-kit consumer index + kit library (#2571): drives the kit NODES on the L0 network (one per
  // distinct kit in use, edged to every consuming project — showing which projects share a kit).
  const kitUsage = useAppStore((s) => s.kitUsage);
  const kits = useAppStore((s) => s.kits);
  // The cross-graph LIBRARY dimension (#3133): the algorithms/sounds each kit's components import. Memoized
  // on `components` ALONE — deriving it scans every component's source, and `projects` below re-identifies
  // on each status tick (faults/stall/`now`), so folding the scan into the `projectData` memo would re-run
  // it on every poll. This way the scan runs only when the component library actually changes.
  const components = useAppStore((s) => s.components);
  const libraryRefs = useMemo(() => resolveKitLibraryRefs(components), [components]);
  // The MCP-CONTRACT dimension (#3786, Phase 1 inter-app contracts): the MCP server store drives one
  // external contract node per SCOPED server (a global server is skipped), edged from each consuming
  // project — showing which projects contract with which external MCP servers.
  const mcpServers = useAppStore((s) => s.mcpServers);
  // Per-project auto-triage toggle (#2265) — gates the fault→fix loop; surfaced in the node inspector.
  // Per-node OFF toggle (#3239) — the user has deactivated these nodes; they render greyed (health `off`)
  // and read "off" over any live status. Persisted, so it continues from the last session.
  const glanceOff = useAppStore((s) => s.glanceOff);
  // Ending a stuck agent's session (#3049): disabling the cell drops it from livePaneIds (so the node
  // stops reading as live) and setPaneStatus clears a stale "run" dot. fleetStartProject re-enables the
  // cell on the next launch, so this is self-reversing — "Relaunch fleet" respawns it fresh.
  const reapPane = useAppStore((s) => s.reapPane);
  const setPaneStatus = useAppStore((s) => s.setPaneStatus);
  // The per-pane run status — drives the fleet-drill agent nodes' live activity (#3252, `applyFleetLiveStatus`).
  const paneStatus = useAppStore((s) => s.paneStatus);
  // THE BACKEND'S OWN VIEW of which PTYs are alive (`glance-reads-session-liveness-from-the-backend-that-owns-it`).
  //
  // `paneStatus` and `paneClaudeActive` above are written only by a mounted TerminalView catching the
  // one-shot OSC-100 marker as it goes past, so a session started headlessly and left running — every
  // surface operator, every local-model session — was invisible to both and its node rendered `off`
  // while the reaper reported `status: run`. The reaper scans that marker out of the raw PTY stream and
  // keeps it as STATE, so it is harness-agnostic and survives a terminal that was never opened.
  //
  // Read on the STALL cadence rather than a faster one: this answers "does a session exist", which
  // changes when one is launched or reaped, not between frames. `{}` on failure would blank every node
  // to `off`, so a failed read KEEPS the last snapshot — the same judgement the integration band makes
  // below, for the same reason.
  const [runState, setRunState] = useState<Record<string, string | undefined>>({});
  usePoll(async (isCancelled) => {
    const rows = await safeInvoke<[string, number, string][] | null>("pty_activity", undefined, null);
    if (isCancelled() || !rows) return;
    setRunState(Object.fromEntries(rows.map(([paneId, , status]) => [paneId, status])));
  }, STALL_POLL_MS, []);
  // #4005 — panes STOPPED waiting on the user (permission prompt / input wait), from the shared
  // pane-activity read. Drives the `attention` health so a blocked session is visible without drilling.
  const paneAttention = useAppStore((s) => s.paneAttention);
  // Memoized so the fleet-status memo below is not invalidated by a fresh Set on every render.
  const attentionPanes = useMemo(
    () => new Set(Object.keys(paneAttention).filter((p) => paneAttention[p])),
    [paneAttention],
  );
  // #3916: quarantine is a FIRST-CLASS node state now — a warden hard-pause used to be invisible
  // here, so a killed worker read as a plain `off` node (indistinguishable from never-launched).
  const quarantinedPanes = useAppStore((s) => s.quarantinedPanes);
  // Confirm before the BULK "End sessions" (#3052) — stopping a whole fleet at once warrants a guard.
  const { confirm, dialog: endAllDialog } = useConfirmDialog();
  // HEALTH axis (#2541, was #2265): the worst unresolved fault per project (from `bsc errors`) overlaid
  // onto each node — escalating health to warning/error and carrying the fault title as the reason.
  const faults = useGlanceFaults(useMemo(() => projectsBase.map((p) => p.id), [projectsBase]));
  // Agent-health watchdog (#2541): `coord.state.waiting` carries each parked `bsc-wait` + its epoch; a
  // wait overstaying the threshold escalates its project to a warning. `now` ticks on the same slow
  // cadence (kept out of render — `Date.now()` is impure) so a threshold crossing surfaces without a
  // coord change.
  const coord = useCoordLog();
  // #4010 — sessions parked by `bsc-maintain`. Memoized for the same reason: a fresh Set each render
  // would invalidate the fleet-status memo below on every tick.
  const maintainingPanes = useMemo(
    () => new Set(coord.state.maintaining.map((m) => m.session)),
    [coord.state.maintaining],
  );

  const [now, setNow] = useState(0);
  usePoll(async (isCancelled) => { if (!isCancelled()) setNow(Date.now()); }, STALL_POLL_MS, []);
  // Overlay order: base (merge+liveness) → STALL (waiting/warn) → FAULT (error) → OFF (#3239) last, so a
  // real error beats a stall and both beat the resting state — but the user's manual OFF beats them all
  // ("if it's not idle then it should be off").
  // A stall is only a stall while the agent is still THERE (#3429) — a wait parked by a since-dead session
  // pinned its project orange forever, since nothing ever clears it and `now - w.at` only grows.
  const liveWaiting = useMemo(() => liveWaits(coord.state.waiting, livePaneIds), [coord.state.waiting, livePaneIds]);
  // THE TAB STRIP COMES FIRST: the project list below is scoped to the active tab, so which tab is
  // active has to be known before the graph is built.
  const networks = useAppStore((s) => s.networks);
  const glanceTabs = useMemo<TabItem[]>(
    () => networks.map((n) => ({ id: n.id, label: n.name, hint: "one architect · its projects" })),
    [networks],
  );
  // UNCONTROLLED, deliberately: the active page is read from `activePageTab["glance"]`, which is what
  // lets `bsc navigate page <networkId>` reach a tab and makes the choice survive a restart. A
  // controlled tab would hold the selection in this component, where navigate cannot see it.
  const { tabs, activeId, select, reorder, tearOff } = usePageTabs("glance", glanceTabs);
  const page = pageOverride ?? activeId;

  const allProjects = useMemo(
    // Just the user's real projects. The synthetic base-studio-code node (#3319) that used to be appended
    // here is GONE (#the-app-drills-into-a-project-that-was-deleted): it named a project with no hub, and
    // once that hub was migrated into `studio-code` and deleted it was a SECOND node for the same app —
    // the one the studio sessions and every live debug session hung off. They fold into the real
    // project's drill now, so there is one node for the app rather than two. (The STUDIO fold that
    // also lived on that path is retired — see the note at the composition below.)
    () => applyOffHealth(applyFaultHealth(applyStallHealth(projectsBase, liveWaiting, now), faults), glanceOff),
    [projectsBase, liveWaiting, faults, now, glanceOff],
  );
  // SCOPED TO THE TAB. A network is a domain — the set of projects that share one concern — so a network
  // tab draws only the projects filed into it, and the fixed `All projects` tab keeps the unfiltered
  // view a user with no networks still needs.
  //
  // The architect the projects edge to is the NETWORK, not a persona: one architect per network is the
  // whole point of the split, and `architect` on a ProjectLite means "which architect node this edges
  // to" — an id that is now a network id. Overwritten rather than read from the row, because the
  // network is what decides it; the per-project `bsc project architect set` column is the older,
  // persona-scoped answer and no longer the one the graph draws.
  const networkTab = useMemo(() => networks.find((n) => n.id === page) ?? null, [networks, page]);
  // NO TAB RESOLVED ⇒ NO PROJECTS, not every project. There is no all-projects lens any more, so the
  // fallback that used to mean "show everything" would now silently draw an unscoped graph under a tab
  // that claims to be one domain. This state is transient by construction — it is the frame before
  // `hydrateNetworks` returns, and that reconcile creates `kitchen` rather than leaving nothing.
  const projects = useMemo(
    () => (networkTab
      ? allProjects.filter((p) => p.network === networkTab.id).map((p) => ({ ...p, architect: networkTab.id }))
      : []),
    [allProjects, networkTab],
  );
  // L0 — the project-network graph (nodes = real projects + UI-kit nodes #2571 + the algorithm/sound
  // library nodes their kits require #3133 + external MCP-contract nodes #3786, edges = the user-drawn
  // relationships #2253 + one kit→project edge per consumer #2571 + the transitive project→library
  // `requires` edges #3133 + one project→mcp `uses-mcp` edge per scoped consumer #3786).
  // The ARCHITECT band (#glance-architect-band) — tier 1 of the funnel, from the persona store. Filtered
  // by ROLE rather than by a hardcoded id, so a second architect persona shows up without a code change
  // (funnel-architect-front-door makes multiple architects a first-class case).
  // ONE ARCHITECT NODE PER NETWORK — the node id carries the NETWORK id (`architect:network-kitchen`),
  // which is what `studioPaneIdForNode` turns into the pane `network-kitchen:architect`.
  //
  // This replaces one node per architect PERSONA. That model drew every project to a shared persona and
  // its drill-in ignored which architect was clicked, always rendering the same global studio team — so
  // with an architect per network it would have been actively wrong rather than merely uninformative.
  //
  // `All projects` gets NO architect node: no single architect owns everything, and inventing one there
  // would draw an edge nobody could act on.
  const architects = useMemo(
    () => (networkTab ? [{ id: networkTab.id, name: `${networkTab.name} architect` }] : []),
    [networkTab],
  );
  // The INTEGRATION band's two inputs (`the-integration-band-gets-its-data-path`) — which projects
  // DECLARED which integrations at Discovery, joined to what each registered connector last verified.
  //
  // ONE backend read rather than two, and rather than shelling out to `bsc`: the command already holds
  // both stores, so it classifies each verdict against the manifest registered NOW. That matters —
  // a stored `live` whose manifest has since been edited must arrive here as `stale`, and this side
  // has no manifest to work that out for itself.
  //
  // Polled on the same cadence as the rest of the cockpit, because a verdict changes when the
  // Integrator runs a check, which this window does not otherwise learn about. An empty read is the
  // normal state on an install with nothing declared, and contributes no nodes at all.
  const [integrationBand, setIntegrationBand] = useState<{
    declared: DeclaredIntegrationRow[];
    connectors: ConnectorStatusRow[];
  }>({ declared: [], connectors: [] });
  usePoll(
    async (isCancelled) => {
      // The fallback is NULL, not an empty band, and that distinction is deliberate: a failed read and
      // an install with nothing declared must not look the same. On failure we keep whatever the band
      // last held rather than blanking it, so a transient backend error cannot make a real integration
      // vanish from the cockpit for 30 seconds.
      const band = await safeInvoke<{
        declared?: DeclaredIntegrationRow[];
        connectors?: ConnectorStatusRow[];
      } | null>("glance_integration_band", undefined, null);
      if (isCancelled() || !band) return;
      setIntegrationBand({ declared: band.declared ?? [], connectors: band.connectors ?? [] });
    },
    INTEGRATION_POLL_MS,
    [],
  );

  const projectData = useMemo(
    () =>
      buildGlanceData(
        projects,
        projectLinks,
        kitUsage,
        kits,
        libraryRefs,
        mcpServers,
        architects,
        integrationBand.declared,
        integrationBand.connectors,
      ),
    [projects, projectLinks, kitUsage, kits, libraryRefs, mcpServers, architects, integrationBand],
  );
  const projectModel = useMemo(() => timedSync("buildGraph:glance-project", () => buildGraph(projectData.rawNodes, projectData.rawEdges)), [projectData]);

  // ONE TAB PER NETWORK, appended after the fixed pair — the same shape Teams uses for its stored
  // teams, and the reason `usePageTabs` needed no change: it takes `defs` from the caller each render
  // and owns only order + active id, and `orderTabs` appends new defs while ignoring stale ids.
  const { prompt, dialog: promptUi } = usePromptDialog();
  const addNetwork = useAppStore((s) => s.addNetwork);
  const renameNetwork = useAppStore((s) => s.renameNetwork);
  const removeNetwork = useAppStore((s) => s.removeNetwork);
  const openNetworkArchitect = useAppStore((s) => s.openNetworkArchitect);
  const closeNetworkArchitect = useAppStore((s) => s.closeNetworkArchitect);

  /** A tab is a network when the store holds one under that id — never by parsing the id, so the two
   *  cannot disagree about what `fleet` is. */
  const isNetworkTab = useCallback((id: string) => networks.some((n) => n.id === id), [networks]);

  // THE OPEN IS WHAT STARTS THE SESSION. A network's architect is mounted lazily, exactly as a studio
  // is: showing its tab is the declaration that it should be warm. Without this the session built in
  // `a-network-architect-mounts-and-runs` exists and never runs.
  useEffect(() => {
    if (!isNetworkTab(page)) return;
    openNetworkArchitect(page);
  }, [page, isNetworkTab, openNetworkArchitect]);

  const onAddNetwork = useCallback(async () => {
    const name = await prompt({
      title: "New network",
      label: "A network is a domain — its own graph, its own architect, and the projects that share one concern.",
      placeholder: "finance",
      confirmLabel: "Create",
    });
    if (!name) return;
    select(addNetwork(name));
  }, [prompt, addNetwork, select]);

  const onCloseNetwork = useCallback(async (id: string) => {
    if (!isNetworkTab(id)) return; // the fixed pair is not closeable
    const { ok, blockedBy } = await removeNetwork(id);
    if (!ok) {
      // REFUSED, not cascaded: a network does not own its projects (membership is a column on each
      // project row), so deleting it would leave them pointing at nothing — in `bsc project list` and
      // in no tab. Naming them is what makes the refusal actionable.
      await prompt({
        title: "That network still has projects",
        label: `Move or unfile these first (\`bsc project network set <key> <network>\`): ${blockedBy.join(", ")}`,
        confirmLabel: "OK",
        allowEmpty: true,
      });
      return;
    }
    closeNetworkArchitect(id);
  }, [isNetworkTab, removeNetwork, prompt, closeNetworkArchitect]);

  const onRenameNetwork = useCallback((id: string, name: string) => {
    // Display-only. The id is frozen because the architect's pane id and workspace dir derive from it.
    if (isNetworkTab(id)) renameNetwork(id, name);
  }, [isNetworkTab, renameNetwork]);

  const [sel, setSel] = useState<{ type: "node" | "edge"; id: string } | null>(null);
  // The drilled agents whose live PTY streams are morphed open in the graph (#2369 → MULTI, #3361).
  // Each carries the LATTICE CELL it occupies — signed, so a node left of the anchor holds a cell left
  // of it (#3367). Placements are stable: opening or closing one morph never moves another.
  const [placements, setPlacements] = useState<MorphPlacement[]>([]);
  // The node the grid is anchored on: the FIRST one opened. Slot 0 sits centred on it, so opening a
  // single node looks exactly as it always has and the grid only becomes visible from the second morph.
  // Held as an ID (not coords) so the grid tracks the graph when the model re-lays-out, and RETAINED
  // even if the anchor's own morph closes, so the remaining morphs never shift under the user.
  const [gridAnchorId, setGridAnchorId] = useState<string | null>(null);
  // The grid's SHARED cell size — any morph's resize handles drive it, so they all resize as one.
  const [cell, setCell] = useState<CellSize>(DEFAULT_CELL);
  // The PREVIEW node morphed open (#2623) — the finished app rendered in the graph. Closed by default.
  const [previewOpen, setPreviewOpen] = useState(false);
  const [hoverNode, setHoverNode] = useState<string | null>(null);
  const [hoverEdge, setHoverEdge] = useState<string | null>(null);
  const [showCycle, setShowCycle] = useState(false);
  const [search, setSearch] = useState("");
  // Resume (#glance-resume): in-flight flag + a transient status line (a failure reason, or a launch
  // note such as "2 completed workers relaunching into maintenance").
  // No `resuming` flag any more: the only thing that read it was the project Resume button's
  // `disabled`, and the per-node fallback below reports through `resumeMsg` instead.
  const [resumeMsg, setResumeMsg] = useState<string | null>(null);
  // Drill (#…): clicking a project on the Network graph animates INTO that project's fleet-relationship
  // graph — the SAME canvas, a different graph (L0 project network → L1 agent fleet). `drill` is the
  // drilled project node id, held in the STORE so the app-wide nav history (mouse back/forward) can
  // drive it (see useNavHistory).
  // An ARCHITECT can never be a drill target, however the value arrived. `onNodeClick` opens its
  // session instead of drilling, but `glanceDrill` is ALSO restored by the app-wide nav history (mouse
  // back/forward) and reachable by `bsc navigate` — so a drill recorded before this change, or set from
  // outside, would land on a branch that no longer exists and fall through to the sample placeholder.
  // Guarding at the source is what makes `isStudioDrill` genuinely dead rather than merely unlikely.
  // PER TAB (`each-glance-tab-owns-its-own-drill`): the drill belongs to the network being shown, so a
  // depth reached on one domain's graph is not applied to the next. It was one global value, and
  // switching tabs carried the other tab's drill into a graph that does not contain that node.
  const rawDrill = useAppStore((s) => s.glanceDrill)[page] ?? null;
  const drill = rawDrill && isArchitectNodeId(rawDrill) ? null : rawDrill;
  // #4050 — per-stream owned-issue completion for the DRILLED project. One read, partitioned in
  // memory; null while not drilled, so nothing polls at the project-network level.
  const planDbProgress = useStreamProgress(drill ?? null);
  // ONE LAYER (`the-project-drill-is-one-layer-and-every-node-opens-its-session`). A project drill has no
  // crate or feature sub-layer, and no session mode decides how many it has: every stream is exactly one
  // node, drawn from `bsc fleet graph`, and clicking it opens that stream's session.

  const setDrill = useAppStore((s) => s.setGlanceDrill);
  // The MORPH is a first-class viewer of an app-owned studio session (#3357): opening a studio node starts
  // its session (lazily) and holds the idle reaper off for as long as the morph is open, exactly like its
  // page dock. Null for every other node, so the hook no-ops. (The debugger is NOT a studio here — its
  // lifecycle is the Settings toggle, not the reaper.)
  // MULTI (#3361): every open studio node must be pinned, not just the newest — otherwise the idle
  // reaper could kill a session the user has on screen in another morph.
  // Whether the current drill shows APP-OWNED STUDIO SESSIONS rather than a project's fleet. TWO
  // drills do (#architect-node-expands-into-system-sessions): the base-studio-code project (every
  // app-owned session, incl. the debugger + request pool) and the ARCHITECT node (just the sessions
  // its verbs command). They differ in WHICH sessions they show, but every downstream behaviour —
  // pinning them against the reaper, live status, opening a node, the morph, no fleet-resume — is
  // identical, because both graphs use the same Studio Network position ids. One predicate, so a new
  // studio drill cannot pick up four of the six behaviours and silently miss the rest.
  // Only the ARCHITECT drill is studio-ONLY now. The app's own project used to be the other one; it is a
  // real plan.db project that happens to ALSO draw the studio sessions, so it is not this — it takes the
  // fleet overlay, the fleet resume and the fleet's own node semantics, and the studio nodes riding on it
  // are handled per NODE (`studioPaneIdForNode`) rather than by re-classifying the whole drill.
  // NOT gated on the drill any more (#the-app-drills-into-a-project-that-was-deleted): a studio morph can
  // now be open on the app's own PROJECT drill, and a studio the user is watching there must pin the idle
  // reaper off exactly as it did on the old studio-only drill. `isStudioId` already answers false for
  // every fleet cell, so the gate only ever narrowed which studios got protected.
  const openStudioIds = useMemo(
    () => occupants(placements).filter(isStudioId),
    [placements],
  );
  useStudioViewers(openStudioIds);
  const closeStudio = useAppStore((s) => s.closeStudio);
  // The drilled project's fleet, translated from plan.db. The store's `planFleet` only mirrors the ACTIVE
  // project, so for any OTHER project we load its fleet straight from its own plan.db (useProjectFleet).
  // Prefer the live store copy when it has streams so the active project never flashes sample → real.
  const loadedFleet = useProjectFleet(drill);
  const storeFleet = drill ? planFleet[drill] : undefined;
  // plan.db WINS once it has loaded; the persisted mirror only covers the gap until then.
  //
  // It used to be the other way round, which made the persisted `planFleet` outrank the store of record:
  // a `bsc plan fleet set` was durable but invisible to a running app until the app happened to rewrite
  // its own copy. That inverts this project's rule — persist is a CACHE, not a source — and it is the
  // mechanism behind a whole class of "I changed the store and nothing happened".
  //
  // NOT a plain inversion: the original ordering existed to stop the active project flashing sample→real
  // while the async read lands. `useProjectFleet` returns null until its read resolves, so preferring a
  // LOADED non-empty fleet keeps that guard — the mirror still renders during the load — while making the
  // authoritative copy win the moment it exists.
  const effectiveFleet = loadedFleet && loadedFleet.streams.length > 0 ? loadedFleet : storeFleet;
  // #3931: which streams the dependency gate is holding, so their nodes explain themselves instead of
  // rendering as anonymous dark `off` nodes. Read-only — this never launches anything.
  const heldStreams = useFleetHeld(drill, effectiveFleet?.streams);

  // #4102 — the issue-state overlay. Ownership comes from the fleet plan (local, always available);
  // GitHub supplies only open/closed. One batched query per repo, and none at all when not drilled.
  const fleetStreams = effectiveFleet?.streams ?? NO_STREAMS;
  const fleetIssues = useFleetIssueState(fleetStreams);
  // The bar's input: refs from the plan, done-ness from plan.db statuses UNION the GitHub overlay.
  // #4050 read `total` from plan.db's issue rows, which are empty for a fleet assembled outside a full
  // planner run — so every node reported `total: 0` and the (correct) `total > 0` guard hid the bar
  // for good. Deriving `total` from what a stream OWNS is the fix; `mergeStreamProgress` keeps plan.db
  // answering for any stream that owns no refs, so nothing that worked before regresses.
  const streamDone = useMemo(
    () => mergeStreamProgress(
      // #4122: the DIRECTOR node carries the whole board — every stream's issues unioned — because it
      // is the one agent accountable for all of them rather than a lane. `bsc fleet graph` gives its node
      // the fixed id "director", which is what this keys.
      fleetPlanProgress(
        fleetStreams,
        unionDone(planDbProgress.doneRefs, fleetIssues.done),
        effectiveFleet?.director?.enabled ? "director" : undefined,
        // `glance-progress-ref-namespace-split`: a stream's refs and plan.db's refs are separate
        // ownership records that need not share a namespace. Passing what plan.db KNOWS lets the ref
        // path stand aside when its refs resolve to nothing, instead of winning with a denominator whose
        // numerator can never move — which is how 24 of 25 streams, and the director, all read 0/N.
        planDbProgress.knownRefs,
      ),
      planDbProgress.byStream,
    ),
    [fleetStreams, planDbProgress, fleetIssues.done, effectiveFleet?.director?.enabled],
  );

  // The DIRECTOR's last resort: the project's own progress, from the same read the L0 node counts.
  //
  // Its bar is the whole board by design (#4122), so when the ref path cannot answer — every stream ref
  // in a namespace plan.db has never seen — the honest number is not 0, and it is not the sum of the
  // per-stream rows either (that omits every issue no stream owns). It is the project's, which is
  // exactly what L0 shows. This is what makes the two levels agree rather than merely look similar.
  const streamDoneWithDirector = useMemo(() => {
    const id = effectiveFleet?.director?.enabled ? "director" : null;
    if (!id || streamDone.has(id) || planDbProgress.overall.total === 0) return streamDone;
    const out = new Map(streamDone);
    out.set(id, planDbProgress.overall);
    return out;
  }, [streamDone, effectiveFleet?.director?.enabled, planDbProgress.overall]);

  // #4102 — the Plan screen's data for one node. A fleet node's id IS its stream id, so this is a map
  // lookup rather than another join. Returns undefined for a node that is not a planned worker (the
  // director, a studio session, the debugger), which is what omits the tab rather than showing an
  // always-empty one.
  const planFor = useCallback((nodeId: string): DockPlan | undefined => {
    const stream = fleetStreams.find((st) => st.id === nodeId);
    if (!stream) return undefined;
    return {
      refs: stream.issues ?? [],
      states: fleetIssues.states,
      planClosed: planDbProgress.closedByRef,
      progress: streamDone.get(nodeId),
      // Only claim the overlay is missing once it has actually settled — saying so while the fetch is
      // in flight would flash "connect GitHub" at a connected user.
      unresolved: !fleetIssues.loading && fleetIssues.states.size === 0,
      loading: fleetIssues.loading,
    };
  }, [fleetStreams, fleetIssues.states, fleetIssues.loading, streamDone, planDbProgress.closedByRef]);

  const drillNode = drill ? projectModel.nodes.find((n) => n.id === drill) ?? null : null;
  // Name the drilled project in the titlebar crumb (#3041) — "" on the un-drilled network overview.
  useCrumbEntity("glance", drillNode?.slug ?? "");
  // Whether the drilled project's build is COMPLETE (#2623) — drives the ▷ preview node in the drill.
  const drillComplete = useProjectComplete(drill);
  // The verify-build state (#2623): the built PreviewSource + in-flight flag; the morph's "Build to
  // preview" button kicks the Rust `verify_build`, which resolves the stack, builds + serves, and returns
  // a PreviewSource (null until the backend command lands — the invoke degrades gracefully).
  const previewSources = useAppStore((s) => s.previewSources);
  const previewBuilding = useAppStore((s) => s.previewBuilding);
  const setPreviewSource = useAppStore((s) => s.setPreviewSource);
  const setPreviewBuilding = useAppStore((s) => s.setPreviewBuilding);
  const buildPreview = useCallback((key: string) => {
    setPreviewBuilding(key, true);
    void safeInvoke<PreviewSource | null>("verify_build", { projectKey: key }, null)
      .then((src) => { if (src) setPreviewSource(key, src); })
      .finally(() => setPreviewBuilding(key, false));
  }, [setPreviewBuilding, setPreviewSource]);
  // The reviewer loop for the open preview (#2623 slice 5b): capture a shot → Claude review → confirm-gated inbox.
  const previewReview = usePreviewReview(drill);
  // DOES THIS PROJECT HAVE A DIRECTOR? Answered from EVIDENCE — `livePaneIds` is tab membership, which
  // this file documents as "a durable, symmetric this-agent-has-a-terminal signal for BOTH workers AND
  // the DIRECTOR", added precisely because the director is not a stream and sits idle between prompts.
  // A boolean, not the set, so the graph memo below re-runs when a director appears or goes — not on
  // every liveness poll.
  const hasDirectorPane = !!drill && livePaneIds.has(fleetPaneId(drill, "director"));
  // THE DRILL, RESOLVED (`glance-renders-a-graph-the-agents-surface-resolves`). Every node's title, label
  // and owner, every edge's archetype and the director tier come back DECIDED from `bsc fleet graph`; this
  // page renders them. The open director pane is REPORTED, so the resolver can draw a director no plan
  // store remembers. It re-reads when the fleet mirror or the persona library changes — both keep their
  // reference when nothing moved, so neither re-reads on a poll.
  const fleetGraph = useFleetGraph(drill, hasDirectorPane, effectiveFleet, personas);
  const fleetData = useMemo(() => {
    if (!drillNode) return null;
    // NOTHING IS INVENTED, AND NOTHING REAL IS HIDDEN — now enforced where the graph is resolved rather
    // than here. `bsc fleet graph` draws no team a plan does not name and no director that has neither a
    // plan nor a session, and it does draw a director whose pane is open. A project with neither is an
    // empty graph, which is the truth.
    const base = fleetGraph ? fleetGraphToGlance(fleetGraph) : EMPTY_FLEET_DATA;
    // Add the preview node when the project has finished building (idempotent, no-op while building),
    // then — for the app's OWN project — the app-owned studio sessions and the request sessions they
    // filed (#the-app-drills-into-a-project-that-was-deleted), and finally any request session THIS
    // project's director filed, which has no Studio Network position to hang off
    // (#debug-nodes-hang-off-the-session-that-filed-them).
    //
    // THE STUDIO FOLD IS GONE (`the-project-drill-has-one-source-for-its-nodes`). `withStudioSessions`
    // folded the Studio Network team's sessions into the app's OWN project drill, so studio-code — and
    // only studio-code — drew seven nodes that no plan of its own declared: designer·react,
    // designer·react-native, librarian·rust, librarian·typescript, architect, sound-designer,
    // integrator. It was a SECOND source for a concept the fleet already had (`fleet.systemSessions`),
    // and the two could not be reconciled from the data: clearing the fleet's list changed nothing
    // because the nodes came from `org-planning-studio` in orgs.db, through an `isAppProject`
    // special case. The studios are app-owned and belong to the Studio Network — the Teams workspace
    // still renders that team, which is where a team graph belongs.
    //
    // ORDER still matters for what remains: the request drawers run most-related to least, and the
    // SWEEP runs LAST (#every-live-debug-session-is-visible-in-the-app-drill) so it adds only what the
    // earlier drawer did not, and can never take an edge away from one that wanted to draw it.
    const withPreview = withPreviewNode(base, drillComplete);
    const withRequests = withProjectRequestNodes(withPreview, drill ?? "", activeDebugRequests);
    // Finally, in the APP's own drill ONLY: a node for every live session the two drawers above could
    // not relate to anything — a request filed by a human at a shell, or by another project's director.
    // Visibility is unconditional; a relationship is not. Gated on the app project so an unrelated
    // project's drill does not acquire debug nodes for work that has nothing to do with it.
    // THE DIRECTOR TIER arrives resolved: in the app's own drill `bsc fleet graph` already draws every
    // other project in its network that has a director, as a PEER of this director, never a report. Each
    // request those directors filed is edged to them here — after they are drawn, and before the sweep,
    // which only adds what nothing else drew and so cannot strip an edge from a drawer.
    const withDirectorReqs = isAppProject(drill)
      ? withDirectorRequestNodes(withRequests, activeDebugRequests)
      : withRequests;
    // NO FEATURE OR CRATE FOLD. Streams are the nodes: a feature grouping node stood in for the streams it
    // covered, and a `surface:<crate>` roster node resolved no pane, so both made a click that opened
    // nothing. A UI stream carries its feature slug as its label, decided by `bsc fleet graph`.
    return isAppProject(drill)
      ? withUnparentedRequestNodes(withDirectorReqs, activeDebugRequests)
      : withDirectorReqs;
  }, [drillNode, fleetGraph, drillComplete, activeDebugRequests, drill]);
  // Overlay the LIVE session state onto the drilled fleet's agent nodes (#3252) — the L1 twin of the L0
  // stall/fault overlays: an agent lifts off its planned idle to building/waiting/warning per its session.
  // Applied to rawNodes BEFORE buildGraph so the rollup + inherited-health recompute over the live values.
  const liveFleetData = useMemo(
    () =>
      fleetData && drill
        ? {
            ...fleetData,
            // The base-studio project's nodes are STUDIO sessions, keyed by their stable app-owned pane id
            // (`studioPaneIdForNode`) — not `fleetPaneId(project, node)`. Running the fleet overlay over them
            // looked up a pane that never exists, so none was ever found live (#3421).
            // The two overlays COMPOSE now, they no longer compete (#the-app-drills-into-a-project-that-was-deleted).
            // One drill can hold both kinds, so choosing a single overlay for the whole graph would have to be
            // wrong for one of them — and it already was, for the studio nodes a project TEAM draws:
            // #every-system-session-shows-one-node-per-technology made those openable on a project drill
            // without making them reportable, so such a node opened a live session while rendering `off`.
            //
            // Fleet first, studio second. `applyStudioLiveStatus` leaves a node with no app-owned pane
            // untouched, so it corrects exactly the nodes the fleet pass had no key for and nothing else;
            // running it second is what lets it override that pass's `off` fall-through for them.
            rawNodes:
              applyStudioLiveStatus(
                    applyFleetLiveStatus(withStreamProgress(fleetData.rawNodes, streamDoneWithDirector), drill, { livePaneIds, paneStatus, runState, waiting: coord.state.waiting, now, quarantined: quarantinedPanes, held: heldStreams, attention: attentionPanes, maintaining: maintainingPanes, ended: endedPanes }),
                    { paneClaudeActive, paneStatus, runState },
                  ),
          }
        : fleetData,
    // `quarantinedPanes` + `heldStreams` belong here: without them the memo keeps a stale overlay, so a
    // newly quarantined worker (#3916) or a stream released by the gate (#3931) would not repaint until
    // some unrelated dep changed.
    [fleetData, drill, livePaneIds, paneStatus, coord.state.waiting, now, paneClaudeActive, runState, quarantinedPanes, heldStreams, attentionPanes, maintainingPanes, endedPanes, streamDoneWithDirector],
  );
  // `refineLayout` rather than a post-process: buildGraph computes every edge's path FROM the node
  // positions, so moving a node after it returns leaves its edges pointing where it used to be. The
  // director/session split therefore runs INSIDE, between layout and edge geometry.
  const fleetModel = useMemo(
    () =>
      liveFleetData
        ? timedSync("buildGraph:glance-fleet", () =>
            buildGraph(liveFleetData.rawNodes, liveFleetData.rawEdges, { refineLayout: splitDirectorSessionTiers }),
          )
        : null,
    [liveFleetData],
  );
  // The ACTIVE graph — the drilled fleet (with live status), else the project network. Everything downstream
  // (canvas, sidebar, focus, cycles, viewport) reads these, so the whole page swaps its graph on drill.
  const data = liveFleetData ?? projectData;
  const model = fleetModel ?? projectModel;

  const vp = useGraphViewport({ w: model.worldW, h: model.worldH });
  // Fit only when a node is OPENED/closed — i.e. the DRILL target changes (L0 network ⇄ an L1 fleet) —
  // plus on mount and page change (#2554). Keying on `drill`, NOT `model`: `model` gets a fresh
  // reference on every data poll (the liveness/fault/stall overlays recompute it), and depending on it
  // re-fit the graph every few seconds, wiping out the user's pan/zoom. `fit` reads the current world
  // via a ref, so the deferred call still fits the freshly-swapped graph.
  const { fit, restoreView, hasUserMoved } = vp;
  // WHICH GRAPH IS ON SCREEN — the only thing the fit may key on.
  const shownGraph = drill ? `drill:${drill}` : "network";
  // The LIVE view, in a ref so the switch effect can save the OUTGOING tab's position without this
  // effect re-running on every pan frame.
  const liveView = useRef(vp.view);
  useEffect(() => { liveView.current = vp.view; }, [vp.view]);
  const setGlanceView = useAppStore((s) => s.setGlanceView);
  const shownTab = useRef(page);
  useEffect(() => {
    // A TAB SWITCH: record where the user left the tab they are leaving, then put them back where they
    // left the one they are entering. One `useGraphViewport` instance serves every tab, so without
    // this the incoming graph inherits the outgoing tab's transform and the user lands somewhere
    // arbitrary. Read the map through `getState` rather than subscribing — this component has no
    // reason to re-render when another tab's position is recorded.
    if (shownTab.current !== page) {
      // The morph grid belongs to the graph it was opened over: its placements name nodes of the tab
      // being left, and carrying them across renders nothing (they resolve to no node) while keeping
      // `placements` non-empty — which is what stops `closeChat` ever releasing the anchor. Clearing
      // is what `exitDrill` already does for the same reason, and a tab switch is at least as big a
      // context change as drilling out. The sessions themselves are untouched: closing a morph never
      // ends a PTY.
      setPlacements([]);
      setGridAnchorId(null);
      // RECORD ONLY A POSITION THE USER PLACED. A merely FITTED view is reproducible on return, so
      // recording one buys nothing — and restoring one is actively harmful: `restoreView` sets
      // `userMoved`, which disables `useGraphViewport`'s world-change re-fit, and that re-fit is the
      // only thing that re-frames a graph whose data arrives async (#3433). A frame captured before
      // that tab's data landed would then be pinned forever and render the graph off-screen, with
      // nothing drawn where the user is looking and nothing to click.
      if (hasUserMoved()) setGlanceView(shownTab.current, liveView.current);
      const saved = useAppStore.getState().glanceView[page];
      shownTab.current = page;
      if (saved) { restoreView(saved); return; }
      // No recorded position for this tab — fall through and FIT, which is the right first impression
      // of a graph you have not looked at yet.
    }
    // Otherwise: mount, or the DRILL changed within this tab (L0 network ⇄ an L1 fleet) — a different
    // graph entirely, so frame it. Keyed on `drill`, NOT `model`: `model` gets a fresh reference on
    // every data poll (the liveness/fault/stall overlays recompute it), and depending on it re-fit the
    // graph every few seconds, wiping out the user's pan/zoom. `fit` reads the current world via a ref,
    // so the deferred call still fits the freshly-swapped graph.
    //
    // This used to read `if (page !== "network") return;` — `network` was the FIXED tab id, and every
    // Glance tab is a network id now (`the-graphs-are-the-app` → one tab per network), so the guard
    // matched nothing and the effect never fired at all.
    const id = requestAnimationFrame(() => fit());
    return () => cancelAnimationFrame(id);
  }, [shownGraph, fit, page, restoreView, hasUserMoved, setGlanceView]);

  const selNodeId = sel?.type === "node" ? sel.id : null;
  const selEdgeId = sel?.type === "edge" ? sel.id : null;
  // Ignore a focus target that isn't in the CURRENT graph — e.g. a hover/selection left over from the
  // project network after drilling into a fleet. Otherwise the stale id spotlights nothing and greys out
  // every node on the new page until you mouse over one. Self-corrects on any page change (drill/back/fwd).
  const nodeExists = (id: string | null) => !!id && model.nodes.some((n) => n.id === id);
  const focusNode = nodeExists(hoverNode) ? hoverNode : nodeExists(selNodeId) ? selNodeId : null;
  const focus = focusSets(model, focusNode, hoverEdge ?? selEdgeId, showCycle && model.cyclePairs.length > 0);

  const pickNode = (id: string) => { setSel({ type: "node", id }); setShowCycle(false); };
  const pickEdge = (id: string) => { setSel({ type: "edge", id }); setShowCycle(false); };
  // The app-owned studio session pane id for a node in the base-studio-code drill (#3326/#3357) — every
  // studio node (debugger + designer/librarian/architect) maps to its TerminalHost-hosted session; a
  // library/resource node or any non-studio drill returns null. Non-null ⇒ this node opens an app-owned
  // session, not a fleet cell.
  // NOT gated on `isStudioDrill` any more (#every-system-session-shows-one-node-per-technology): a
  // PROJECT drill lists the same per-technology sessions, and they must open the same way there — click
  // an unstarted one and it lazily starts; click a running one and you get THAT session, because the
  // pane id is stable and the studio mount reuses it rather than spawning a second. `studioPaneIdForNode`
  // already answers null for anything it does not own (a worker, the director, a library), so dropping
  // the gate adds resolution for the studio nodes and changes nothing for the rest.
  const studioPaneId = (nodeId: string): string | null => studioPaneIdForNode(nodeId);
  // A node is MORPHABLE — its terminal openable inline via the in-graph morph — iff its identity pane id
  // (`<project>:<stream>` or `<project>:director`) is a live cell of a launched fleet tab. EVERY fleet
  // node — workers AND the director — gets the morph (#2534/#2542). Drilled only. In the base-studio-code
  // drill EVERY studio session node morphs (#3357): all four now live on the shared TerminalHost, so the
  // host can re-parent their single terminal into the morph. The debugger additionally requires its
  // Settings toggle (its node only EXISTS while the toggle is on); the designer/librarian/architect are
  // always openable — clicking one lazily STARTS its session if it isn't up (stable pane id ⇒ it resumes
  // the same conversation, never a second session).
  const isLiveAgent = (nodeId: string) => {
    // Per NODE, not per drill (#the-app-drills-into-a-project-that-was-deleted). An app-owned session is
    // openable wherever it is drawn — its pane id is stable and its host reuses it — and it is now drawn
    // on the app's own project drill beside real fleet cells. Asking `studioPaneId` FIRST mirrors what
    // `openChats` already does (`studioPaneId(node) ?? fleetPaneId(...)`), so what opens and what reports
    // itself openable cannot disagree.
    if (studioPaneId(nodeId)) return studioNodeHome(nodeId)?.kind === "morph";
    // …and the DRILL GUARD comes after it, because it belongs to the fleet path alone: a fleet pane is
    // `<drill>:<node>`, so without a drill there is no pane to be live. Asked first, it also answered
    // "not openable" for the L0 architect — one of the three gates that made its click do nothing.
    if (!drill) return false;
    return nodeHasLiveSession(fleetPaneId(drill, nodeId), livePaneIds);
  };
  // On the L0 network: a click drills into that project's fleet. Inside a fleet a click checks in on a
  // LIVE agent (morph → terminal, #2401) or selects a non-live one. (Project links are LLM-authored, not
  // drawn by hand — the manual connect-mode was removed, #2737 direction.)
  const onNodeClick = (id: string) => {
    // Inside a fleet: EXPANDING a node is what resumes it (#expanding-a-node-resumes-its-session).
    // Studio nodes already worked this way — `useStudioViewers` starts a studio when its morph opens —
    // and this gives the fleet the same rule, now that the per-node Resume button went with the right
    // pane. `expandNode` covers both the no-pane and the live-but-dead cases.
    if (drill) {
      if (id === PREVIEW_NODE_ID) setPreviewOpen(true);       // the ▷ preview node → render the app (#2623)
      // EVERY OTHER NODE IS A SESSION. The drill is one layer: no crate or feature node opens a second
      // graph, because streams are the nodes and each one's id is the id its pane binds to.
      else expandNode(id);
    }
    // A fenced-BAND node — a cross-graph LIBRARY node (#2571 kit → #3119 kit/algorithm/sound) OR an
    // external MCP-CONTRACT node (#3786) — has no fleet to drill into, so a click just SELECTS it
    // (→ the library/contract inspector).
    else if (isBandNode(projectModel.nodes.find((n) => n.id === id) ?? {})) pickNode(id);
    // An OFF (deactivated) node (#3239): a click SELECTS it (→ the details pane, where the user turns it
    // back on) rather than drilling into a fleet the user has muted.
    else if (glanceOff[id]) pickNode(id);
    // THE ARCHITECT OPENS ITS SESSION, it does not drill. It is an actor you talk to, not a container
    // to navigate into — and it used to drill into `buildArchitectFleetData`, which ignored WHICH
    // architect was clicked and always rendered the same global studio team. That was already
    // degenerate; with one architect per network it would be wrong.
    //
    // `expandNode` is the same gesture a live session node uses inside a drill: the morph opens in
    // place and `studioNodeHome` re-parents the single terminal into it, never spawning a second.
    else if (isArchitectNodeId(id)) expandNode(id);
    else { setDrill(page, id); setSel(null); setShowCycle(false); }
  };
  /**
   * EXPAND a node — and resume whatever it takes to make that expansion show a live agent
   * (#expanding-a-node-resumes-its-session).
   *
   * The placement is made FIRST, unconditionally, so the click is never dead: `openChats` filters
   * placements by `isLiveAgent`, so the cell simply renders as soon as the session comes up. Resuming
   * first and expanding after would leave the user staring at an unchanged graph for the length of a
   * fleet relaunch.
   *
   * Two failure shapes, and the second is the one this codebase keeps rediscovering:
   *   • NO PANE — the node has no session cell at all. Resume it in place if its build tab is still
   *     open (`resumePaneSession`), else bring the fleet back.
   *   • PANE, NO AGENT — `isLiveAgent` is TAB MEMBERSHIP, not "an agent is running" (glanceFleet.ts).
   *     #3998 measured 77 of 78 fleet panes sitting at a bare `$` prompt while reading as live. So a
   *     live node still needs `ensureClaudeRunning`, which types the resume into the shell it already
   *     has — nothing remounts such a pane, so this is the only thing that can revive it.
   */
  const expandNode = (id: string) => {
    // Per NODE, for the same reason `isLiveAgent` is: the app's project drill holds both kinds at once.
    const isStudio = !!studioPaneId(id);
    // THE DRILL GUARD IS FOR THE FLEET PATH ONLY. That path's pane id is `fleetPaneId(drill, id)`, so
    // with no drill there is nothing to expand. A STUDIO node is app-owned — `studioPaneIdForNode`
    // resolves its pane and `decideExpand({ isAppOwnedSession: true })` returns `studio-morph`/`select`,
    // both of which return before anything below reads `drill`.
    //
    // Guarding unconditionally made the NETWORK ARCHITECT's click a NO-OP: `onNodeClick` routes it in
    // the `else` of `if (drill)`, so it runs ONLY at L0 — where `drill` is null by definition — and this
    // line bailed on every click, on every network tab. The session was already warm in its
    // `NetworkArchitectMount`; nothing but this line stood between the user and it.
    if (!isStudio && !drill) return;
    const paneId = !isStudio && drill ? fleetPaneId(drill, id) : "";
    const action = decideExpand({
      isAppOwnedSession: isStudio,
      studioMorphs: isStudio ? studioNodeHome(id)?.kind === "morph" : undefined,
      paneIsLive: !isStudio && isLiveAgent(id),
      paneIsComplete: !isStudio && completedPanes(useAppStore.getState()).has(paneId),
      // `resumePaneSession` is both the probe and the action, so whether a pane can be resumed IN PLACE
      // is only answerable by trying — decided at actuation below rather than guessed here.
      canResumeInPlace: true,
    });
    switch (action.kind) {
      case "studio-morph": openChat(id); return;
      case "select": pickNode(id); return;
      case "refuse-complete": pickNode(id); setResumeMsg(action.reason); return;
      case "expand-and-restart-agent":
        openChat(id); setResumeMsg(null); void ensureClaudeRunning([paneId]); return;
      default: break;
    }
    openChat(id);
    setResumeMsg(null);
    if (resumePaneSession(paneId)) return;   // its build tab was still open — resumed in place
    // EXPANDING A NODE NEVER LEAVES THE GRAPH, and never starts anything but this one session.
    //
    // This used to fall through to `resumeProjectFleet`, whose `fleetStartProject` "navigates to the
    // Console and focuses the build tab" — its own words, in `resumeProject.ts`'s header. So clicking
    // ONE node that had no live pane and no open build tab threw the user off Glance entirely and
    // relaunched every other stream on the way. With 60 surface streams on this drill that is not a
    // near miss, and it made the lexicographer and every un-started surface look broken.
    //
    // `ensureClaudeRunning` is the narrow action instead: it starts the agent for THIS pane and
    // touches nothing else. `not-live` is the one outcome meaning there was no pane to start into —
    // `started` and `already-running` are both success, so treating them as failure would put a
    // message on screen every time a node opened correctly. `not-live` is BENIGN, not a fault:
    // `planResume` documents it as "no PTY yet. Do nothing", and it is reached only once
    // `resumePaneSession` has REFUSED — which happens exactly when the pane has no cwd, i.e. when no
    // launch ever wired this node. So the message says THAT, and names the fleet launch that seats one
    // (the phrasing the Fleet page already uses for the same state).
    //
    // IT MUST NOT NAME THE HEADER RESUME (`glance-names-an-action-that-exists`). That control was
    // DELETED — the block below says so in its own words — and this message outlived it, sending the
    // user to a button that is not there. Observed on politician-review's `lexicographer` node.
    // `glanceNoSessionMessage.test.ts` pins the copy against the record.
    void ensureClaudeRunning([paneId]).then((out) => {
      if (out.get(paneId) === "not-live") {
        setResumeMsg("No session for this node yet — launch this project's fleet from its plan.");
      }
    });

  };
  // OPEN a node's session into a grid cell (#3361). The FIRST open also anchors the grid on that node,
  // so its morph grows exactly where a lone morph always has. Every later node is placed in the
  // DIRECTION its node sits relative to the anchor NODE (#3367) — open one to the left of the anchor and
  // its terminal opens to the left — so the grid reads as a spatial projection of the graph. Idempotent:
  // clicking an already-open node is a no-op, not a second cell.
  const openChat = (id: string) => {
    const node = model.nodes.find((n) => n.id === id);
    if (!node) return;
    // The anchor must be a node in THIS graph. `gridAnchorId` survives a tab switch (it is released
    // only when the last morph closes, or by `exitDrill`), so after opening a morph on one tab it
    // names a node the next tab's model does not contain — and this used to `return prev`, silently
    // swallowing the click. A node that draws and does nothing is the worst failure mode here, so a
    // stale anchor falls back to the clicked node instead: the same rule `resolveGridAnchor` already
    // applies on the READ side, which is where the asymmetry was.
    const anchorNow = gridAnchorId && model.nodes.some((n) => n.id === gridAnchorId) ? gridAnchorId : id;
    setGridAnchorId((prev) => (prev && model.nodes.some((n) => n.id === prev) ? prev : id));
    setPlacements((prev) => {
      const anchor = model.nodes.find((n) => n.id === anchorNow);
      if (!anchor) return prev;
      return placeByDirection(prev, id, { dx: node.x - anchor.x, dy: node.y - anchor.y });
    });
  };
  /** Collapse ONE morph. Its PTY stays alive — the agent is untouched. Frees its cell for a later open;
   *  the surviving morphs keep theirs, and the anchor is retained so the grid never shifts under them —
   *  until the LAST one closes, which releases the anchor so the next session re-anchors on its own node
   *  rather than inheriting a stale grid origin from a node that is no longer open (#3365). */
  const closeChat = (id: string) => setPlacements((prev) => {
    const next = releaseCell(prev, id);
    if (next.length === 0) setGridAnchorId(null);
    return next;
  });
  /** Close everything — the only path that releases the grid anchor, so the next session re-anchors. */
  const closeAllChats = () => { setPlacements([]); setGridAnchorId(null); };
  // Back leaves the project drill for the network — the drill is the only layer below it.
  const exitDrill = () => {
    setDrill(page, null); setSel(null); setShowCycle(false); closeAllChats(); setPreviewOpen(false);
  };
  // Kill ONE live pane (#3049): terminate its PTY (mirrors the console's disable path) and disable the
  // cell so the node drops out of the live set + its stale "run" clears. fleetStartProject re-enables the
  // cell on relaunch, so the teardown is self-reversing — "Relaunch fleet" (#3044) respawns it.
  const killPane = (pid: string) => {
    void safeInvoke("pty_kill", { paneId: pid }, undefined);
    // DORMANT, not DISABLED. Ending a session is meant to stop it, not to retire the pane — but
    // `disabledPanes` is the "the user turned this cell off" flag, and `wakePane` REFUSES a disabled
    // pane outright (deliberately: a director must not override an explicit human pause, which is what
    // the console toggle and the worker-detail Stop button set). So End session was a one-way door —
    // the director could see the worker and never bring it back.
    //
    // `dormantPanes` is the state that already means what End session means: the PTY is gone, the cell
    // renders a placeholder with an explicit Resume rather than relaunching itself, and `wakePane`
    // CLEARS it. Same button, same visible outcome, minus the permanence.
    reapPane(pid);
    setPaneStatus(pid, "idle");
  };
  // END a single agent's session from its morph (#3049): tear it down + collapse the morph.
  const endSession = (nodeId: string, pid: string) => { killPane(pid); closeChat(nodeId); };
  // The drilled project's live sessions — every launched pane under its `<key>:` prefix (director +
  // workers), PLUS the request/debug sessions THIS drill drew above. Their panes are
  // `debug-studio:req-<id>` and so never match the prefix, which is why the requests are passed in:
  // the counter applies the same origin rule the drawers did, so the graph and the toolbar cannot
  // disagree (#a-projects-debug-sessions-are-drawn-but-not-counted — Network Monitor rendered two
  // debug nodes and reported zero). Drives the toolbar "End sessions" button + its count.
  const liveProjectPanes = useMemo(
    () => (drill ? livePanesForDrilledProject(drill, livePaneIds, activeDebugRequests) : []),
    [drill, livePaneIds, activeDebugRequests],
  );
  // END EVERY session for the drilled project (#3052) — the bulk form of endSession, behind a confirm
  // (this stops the whole fleet at once). Self-reversing like the single kill: worktrees/branches/plan.db
  // are untouched, so "Relaunch fleet" restarts them.
  const endAllSessions = async () => {
    const panes = liveProjectPanes;
    if (panes.length === 0) return;
    const ok = await confirm({
      title: `End ${panes.length} session${panes.length === 1 ? "" : "s"}?`,
      message: `Kills every live agent for ${drillNode?.slug ?? "this project"} (director + workers). `
        + `Their worktrees, branches, and plan are kept — "Relaunch fleet" restarts them.`,
      confirmLabel: "End sessions",
      cancelLabel: "Cancel",
      danger: true,
    });
    if (!ok) return;
    for (const pid of panes) killPane(pid);
    closeAllChats();   // every morph's agent is gone (#3361)
  };

  // ── Resume (#glance-resume) ──────────────────────────────────────────────────────────────────
  // THE PROJECT RESUME BUTTON IS GONE. A dormant pane resumes when you open it — `resumePaneSession`
  // in place if its build tab is live, and the per-node path below brings the fleet back when it is
  // not — so a separate "turn them all back on" control was a second way to do what expanding a node
  // already does, and it sat next to a KILL button offering the opposite.
  //
  // `resumeProjectFleet` is no longer called from this workspace at all. The header control went with
  // the commit above; the per-node fallback went with `expanding-a-node-never-navigates-to-the-console`
  // — it relaunched the WHOLE fleet and switched screens because one node had no pane yet. `useFleetGate`
  // still owns the relaunch, which is the one caller that should.
  //


  // The open morphs, DERIVED (never stored) — a morph shows only while its node is still a live agent in
  // the CURRENT fleet, so drilling out (or a nav-history back/forward that swaps `drill`) closes them all
  // by derivation, with no reset effect. #3361 keeps that property PER MORPH: the filter that used to
  // guard one `chatPaneId` now guards each entry, so one agent going away drops just its morph.
  //
  // Each entry carries its SLOT — the grid box it grows into, derived from the anchor node's live coords
  // and the shared cell size. Because slots are discrete, two morphs can never overlap.
  // The stored anchor id can OUTLIVE its node: it is deliberately retained after its own morph closes
  // so the surviving panels never shift. When that node then left the graph this went null and the
  // derivation below dropped EVERY morph at once — and kept dropping them, because `placements` was
  // still non-empty so nothing ever cleared or re-derived the anchor. `resolveGridAnchor` falls back
  // to a surviving placement instead; the grid re-anchors once rather than vanishing.
  const presentNodeIds = new Set(model.nodes.map((n) => n.id));
  const anchorId = resolveGridAnchor(gridAnchorId, placements.map((p) => p.nodeId), presentNodeIds);
  const anchorNode = anchorId ? model.nodes.find((n) => n.id === anchorId) ?? null : null;
  const openChats = placements.flatMap(({ nodeId, col, row }) => {
    // NO BLANKET DRILL GATE. `isLiveAgent` already answers per node — and answers it for an app-owned
    // session WITHOUT a drill — so requiring one here discarded the L0 architect's placement on the
    // very next render, which is why the click looked dead even once `expandNode` let it through.
    if (!anchorNode || !isLiveAgent(nodeId)) return [];
    // A studio pane resolves from the node id alone; a fleet pane needs the drilled project.
    const paneId = studioPaneId(nodeId) ?? (drill ? fleetPaneId(drill, nodeId) : null);
    const node = model.nodes.find((n) => n.id === nodeId);
    if (!paneId || !node) return [];
    return [{ nodeId, paneId, name: node.slug, role: node.roleLabel, at: { col, row } }];
  });
  // END one morph's session (#3049). Ending an APP-OWNED session drops its declaration rather than
  // killing a fleet cell:
  //  • a DEBUG REQUEST session (#debug-nodes-hang-off-the-session-that-filed-them) — kill its PTY, like
  //    a studio. NOTE it is not permanent: `RequestSessionsMount` holds one session per OPEN request, so
  //    ending one while its request is still unresolved lets the next reconcile bring it back. That is
  //    the honest behaviour — the work is still outstanding — and it is what the old Settings toggle
  //    hid by making the whole feature switchable instead.
  //  • a STUDIO (#3357) — drop it from `wantedStudios`, which unmounts its persistent claim; the
  //    `pty_kill` is still explicit, because a studio PAGE dock may hold another claim (End means end,
  //    not "end unless the Design Studio page happens to be mounted").
  // Fleet nodes end their one PTY as before. Scoped to the ONE morph — its siblings stay open (#3361).
  const endChat = (nodeId: string) => {
    const open = openChats.find((o) => o.nodeId === nodeId);
    if (!open) return;
    if (open.paneId.startsWith(DEBUG_STUDIO_PANE_PREFIX)) {
      void safeInvoke("pty_kill", { paneId: open.paneId }, undefined);
      setPaneStatus(open.paneId, "idle");
      closeChat(nodeId);
    }
    else if (isStudioId(nodeId)) {
      // NOT killPane: that also sets the PERSISTED `disabledPanes` flag, which is a fleet-cell concept
      // (fleetStartProject re-enables it). A studio has no cell to re-enable.
      closeStudio(nodeId);
      void safeInvoke("pty_kill", { paneId: open.paneId }, undefined);
      setPaneStatus(open.paneId, "idle");
      closeChat(nodeId);
    }
    else endSession(nodeId, open.paneId);
  };

  // The preview morph shows only while the drill still HAS a preview node — drilling out / to an incomplete
  // project closes it by derivation. `source` is null until the verify-build produces one (#2623 slice 3).
  const previewOn = previewOpen && !!drill && model.nodes.some((n) => n.preview);

  // On opening a live agent's terminal (#2534): bring it into view and ensure a readable zoom, so the
  // in-graph terminal lands legible (option A: it scales with the graph). centerOn is the
  // least-disruptive focus (keeps the current zoom); we only bump zoom up when the graph is small.
  //
  // #3361: centre on the SLOT the morph grew into, not the node — with a grid the two diverge from the
  // second morph on, and it is the panel the user needs to see. Keyed on the open COUNT so it fires once
  // per open (any count) and never on a re-render; the zoom bump stays first-open-only, so adding a
  // fourth morph can't yank the zoom out from under the user.
  const openCount = openChats.length;
  useEffect(() => {
    const newest = openChats[openChats.length - 1];
    if (!newest) return;
    if (openCount === 1 && vp.view.scale < 0.85) vp.zoomTo(1);
    // The world box the newly-opened morph covers AT THE CURRENT ZOOM — a screen-constant card
    // covers less world as you zoom in, so centring on the nominal cell would park the view off the
    // panel. One-shot on open, so reading the committed `view.scale` here is correct rather than stale.
    const box = cellRect(anchorNode!, newest.at, cell, vp.view.scale);
    vp.centerOn(box.left + box.w / 2, box.top + box.h / 2);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openCount]);

  // Auto-clear the transient resume status line so a one-off note/error doesn't linger (#glance-resume).
  useEffect(() => {
    if (!resumeMsg) return;
    const id = setTimeout(() => setResumeMsg(null), 6000);
    return () => clearTimeout(id);
  }, [resumeMsg]);

  const q = search.trim().toLowerCase();
  // GROUPED BY TYPE FIRST — see `NODE_KIND_ORDER` for the order and why it reads that way. Layer then
  // slug still break ties, so within a type the dependency order and the alphabet are both preserved;
  // only the top-level grouping is new. The canvas layout is deliberately untouched.
  const sidebar = model.nodes
    .slice()
    .sort(
      (a, b) =>
        nodeKindRank(a) - nodeKindRank(b) || a.layer - b.layer || a.slug.localeCompare(b.slug),
    )
    .filter((n) => !q || n.slug.toLowerCase().includes(q));
  // An un-drilled project network with no projects yet. We ALWAYS render the (empty) graph now (#3033) —
  // never a blocking empty-state page — and instead surface a one-click "Load demo" in the toolbar so the
  // #2272 demo stays reachable. (Create a project in the Projects workspace via the Rail as usual.)
  // Emptiness is measured on the user's REAL projects (`projectsBase`), not on the graph's node count:
  // since #3319 the always-on base-studio-code studio node is appended to `projects`, so the graph is
  // never node-empty and the demo affordance had become unreachable dead UI (#3411).
  const networkEmpty = !drill && projectsBase.length === 0;

  // WHAT `bsc app go` CAN REACH ON THIS GRAPH (`the-shared-navigation-mechanism-drill-select-and-show`).
  // Published from the SAME handlers a click runs — `onNodeClick`'s routing, `pickNode`, `exitDrill` — so
  // a navigated drill does what a click does. The project drill is the deepest layer: nothing in it is
  // drillable, and entering a node opens its session exactly as a click does.
  useScreenDescriptor({
    workspace: "glance",
    page,
    layer: drill ? "project" : "network",
    // A drill whose graph has not arrived still SHOWS the network (`model` falls back), so its targets
    // are not the real set yet and a reader must wait.
    ready: drill ? !!fleetModel : true,
    drill: drill ? [{ id: drill, label: drillNode?.slug ?? drill }] : [],
    selection: sel?.id ?? null,
    targets: model.nodes.map((n) => ({
      id: n.id,
      label: n.slug,
      drillable: drill ? false : !isBandNode(n) && !glanceOff[n.id] && !isArchitectNodeId(n.id),
      selectable: true,
    })),
    select: (id) => {
      if (id) pickNode(id);
      else { setSel(null); setShowCycle(false); }
    },
    enter: (id) => {
      onNodeClick(id);
      return undefined;
    },
    back: exitDrill,
  });

  return (
    <Screen
      tabs={tabs}
      active={page}
      onSelect={select}
      onReorder={reorder}
      // Tear-off stays for the two FIXED tabs and is refused for a network. `detachedSections` matches a
      // torn-off page against a STUDIO `sectionId`, which a network has none of — so a detached network
      // tab would be a window whose session dock does not follow it. Every other entity-derived tab
      // strip (Sounds, Teams, Algorithms, Data) declines tear-off outright for the same reason; Glance
      // keeps it only where it already worked.
      onTearOff={(id) => { if (!isNetworkTab(id)) tearOff(id); }}
      onAdd={onAddNetwork}
      onClose={isNetworkTab(page) ? onCloseNetwork : undefined}
      onRename={onRenameNetwork}
      pageOverride={pageOverride}
      className="glance-workspace"
    >
      {/* The graph must FILL the screen body (a pan/zoom canvas, not scrolling content); the shared
          .screen-body is a block scroll container, so give it an explicit full-height flex column. */}
      <Box style={{ height: "100%", display: "flex", flexDirection: "column", minHeight: 0 }}>
      <Box style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
    <GraphCanvas
      profileId="glance"
      vp={vp}
      world={{ w: model.worldW || 1600, h: model.worldH || 900 }}
      canvasBackground="radial-gradient(120% 120% at 30% 0%, var(--bg-elev) 0%, var(--bg) 100%)"
      // The infinite viewport grid (#2418, the same graph paper org uses) — 28px tiles; the color
      // matches the old in-world grid (12% fg dots at 0.6 layer opacity ⇒ ~7.2% fg).
      grid gridSize={28} gridColor="color-mix(in oklch, var(--fg) 7.2%, transparent)"
      overlays={<GlanceOverlays drill={!!drill} archetypes={drill ? Array.from(new Set(model.edges.map((e) => e.archetype).filter((a): a is string => !!a))) : []} />}
      railResizable railWidth={266} railMin={200} railMax={420}
      inspectorResizable inspectorWidth={340} inspectorMin={280} inspectorMax={520}
      // Click the empty canvas → clear the selection + any cycle highlight (#2232).
      onBackgroundClick={() => { setSel(null); setShowCycle(false); }}
      toolbar={
        <>
          {/* The 'glance' wordmark + 'project network' subtitle were redundant chrome — the Rail already
              names the workspace and the graph IS the project network — so dropped (#2692). The L1 drill
              breadcrumb went the same way: the titlebar crumb already names the drilled project, so the
              toolbar keeps only the '← projects' button that exits the drill. */}
          {drill && <Button variant="ghost" onClick={exitDrill}>← projects</Button>}
          {/* The project filter moved into the rail's search slot (#2797) — every graph nav menu now leads
              with a search box. Manual connect-mode was removed (#2737): links are LLM-authored, not drawn
              by hand. The graph is configured by the planner/agents, never wired manually here. */}
          <Box style={{ flex: 1 }} />
          {drill
            ? (data.sample
                ? <Chip color="var(--graph-health-warning)">sample fleet · no plan.db fleet</Chip>
                : <Chip color="var(--graph-health-healthy)">real fleet · {model.nodes.length} agents</Chip>)
            : (data.sample && <Chip color="var(--graph-health-warning)">sample topology · preview</Chip>)}
          {/* Project-level bulk kill (#3052): end EVERY live session for the drilled project at once —
              the fast recovery when a whole fleet is soft-locked. Shown only when it has live sessions. */}
          {drill && liveProjectPanes.length > 0 && (
            <Button variant="ghost" danger onClick={endAllSessions}
              title="End every live agent session for this project — Relaunch fleet restarts them">
              End {liveProjectPanes.length} session{liveProjectPanes.length === 1 ? "" : "s"}
            </Button>
          )}
          {resumeMsg && <Text as="span" mono size={10.5} tone="dim" style={{ maxWidth: 260, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={resumeMsg}>{resumeMsg}</Text>}
          {model.cyclePairs.length > 0 && (
            <Box as="button" onClick={() => { setShowCycle((v) => !v); setSel(null); }}
              style={{ display: "flex", alignItems: "center", gap: 7, cursor: "pointer", borderRadius: 7, padding: "6px 11px",
                background: showCycle ? "rgba(242,85,95,.18)" : "rgba(242,85,95,.08)", border: `1px solid ${showCycle ? "rgba(242,85,95,.55)" : "rgba(242,85,95,.3)"}` }}>
              <Text as="span" style={{ color: "var(--graph-health-error)" }}>▲</Text>
              <Text as="span" mono size={11} weight={600} style={{ color: "var(--cycle)" }}>{model.cyclePairs.length} cycle</Text>
            </Box>
          )}
          <ZoomControls vp={vp} step={1.2} />
          <Button variant="ghost" onClick={vp.fit}>fit</Button>
          {/* No projects yet → keep the one-click demo reachable here instead of a blocking empty page (#3033). */}
          {networkEmpty && <Button variant="ghost" title="Load a demo platform — projects, fleets, and libraries" onClick={() => loadDemoState(demoSnapshot())}>Load demo</Button>}
        </>
      }
      rail={
        // Headerless graph-nav menu (#2797): the project/agent filter leads the rail as a search box;
        // the coordination-hazards footer stays pinned below.
        <GraphRail
          tools={<SearchField value={search} onChange={setSearch} placeholder={drill ? "Filter agents…" : "Filter projects…"} aria-label="Filter projects" style={{ width: "100%" }} />}
          footer={model.cyclePairs.length > 0 ? (
            <Box style={{ borderTop: "1px solid var(--border)", padding: "12px 16px" }}>
              <Row gap={7} align="center" style={{ marginBottom: 9 }}>
                <Text as="span" style={{ color: "var(--graph-health-error)" }}>▲</Text>
                <Text as="span" mono size={11} style={{ letterSpacing: "1px", color: "var(--cycle)" }}>COORDINATION HAZARDS</Text>
              </Row>
              {model.cyclePairs.map(([a, b]) => (
                <Box key={a + b} onClick={() => { setShowCycle(true); setSel(null); }}
                  style={{ background: "rgba(242,85,95,.08)", border: "1px solid rgba(242,85,95,.28)", borderRadius: 7, padding: "9px 11px", cursor: "pointer", marginBottom: 6 }}>
                  <Text as="div" mono size={11} style={{ color: "var(--cycle-soft)", marginBottom: 3 }}>dependency cycle</Text>
                  <Text as="div" mono size={11.5}>{model.nodes.find((n) => n.id === a)?.slug} ⇄ {model.nodes.find((n) => n.id === b)?.slug}</Text>
                </Box>
              ))}
            </Box>
          ) : undefined}
        >
          {sidebar.map((n) => {
            const st = HEALTH_META[n.rollupHealth];
            return (
              <RailRow key={n.id} active={selNodeId === n.id}
                onClick={() => onNodeClick(n.id)}
                onMouseEnter={() => setHoverNode(n.id)} onMouseLeave={() => setHoverNode(null)}
                leading={<StatusDot color={st.color} size={7} style={{ boxShadow: st.pulse ? `0 0 7px ${st.color}` : "none" }} />}
                trailing={<>
                  {(n.faults ?? 0) > 0 && (
                    <Text as="span" mono size={9.5} weight={700} title={`${n.faults} unresolved runtime faults`}
                      style={{ flex: "none", color: "#fff", background: "var(--graph-health-error)", borderRadius: 8, padding: "1px 5px", minWidth: 15, textAlign: "center" }}>
                      {(n.faults ?? 0) > 99 ? "99+" : n.faults}
                    </Text>
                  )}
                  <Box style={{ width: 8, height: 3, borderRadius: 2, background: ROLE_COLOR[n.role], flex: "none" }} />
                </>}>
                {n.slug}
              </RailRow>
            );
          })}
        </GraphRail>
      }
    >
      {/* keyed so drilling in/out remounts + replays the shared transition (graphCanvas.css, #2418) */}
      <Box key={drill ?? "network"} className="graph-drill-anim" style={{ position: "absolute", inset: 0 }}>
        <GlanceCanvas
          model={model} dragMoved={vp.dragMoved} zoom={vp.view.scale} counterScale={vp.counterScale} fleet={!!drill}
          focus={focus} selNodeId={selNodeId} selEdgeId={selEdgeId}
          onHoverNode={setHoverNode} onHoverEdge={setHoverEdge} onSelectNode={onNodeClick} onSelectEdge={pickEdge}
          // Every open live-agent terminal, each morphed into its grid slot (#2534 → MULTI, #3361).
          chats={openChats} anchorNode={anchorNode} cell={cell}
          onCloseChat={closeChat}
          onEndChat={endChat}
          // A resize on ANY morph drives the grid's shared cell, so they all resize together.
          onResizeCell={(w, h) => setCell(clampCell(w, h))}
          planFor={planFor}
          preview={previewOn && drill ? {
            nodeId: PREVIEW_NODE_ID, name: drillNode?.slug ?? "app",
            source: previewSources[drill] ?? null,
            building: !!previewBuilding[drill],
            onBuild: () => buildPreview(drill),
            review: previewReview,
          } : null}
          onClosePreview={() => setPreviewOpen(false)}
        />
      </Box>
    </GraphCanvas>
      </Box>
      </Box>
      {/* The bulk "End sessions" confirm (#3052) — rendered regardless of page. */}
      {endAllDialog}
      {promptUi}
    </Screen>
  );
}
